/*
 * 火龙DJ (app-a-djyyk.y2002.com) 原生 Ceru v2 插件
 * 站点：App 网关 https://app-a-djyyk.y2002.com（blueocean 家族，与 Y2002 同域名但独立网关/独立密钥）
 * 音质：64k 标准档(p 域 m4a 封装) / 320k 高品纯格式(o 域 mp3/wav/aac) / flac(仅源格式 flac)
 *
 * 实测（2026-11-19）：
 *   Token : GET /api/System/Token（免签名）→ result.token（UTOKEN，与硬编码兜底值一致）
 *   搜索  : GET /api/Music/Search（小写 MD5 双层签名）→ result.datalist
 *           （id、musicname、nickname、musicurl=/Musics/YYYY/MM/DD/{hash}-{fmt}.m4a、
 *            duration 毫秒、cover 相对路径、searchlrc 恒 null）
 *           Pz=50；上游会随机忽略分页直接倾倒全量，返回数 > Pz 时按 (pi-1)*Pz 切片还原页语义
 *   榜单  : POST /api.html（免签名表单网关，信封 status/msg/data）m=h_r，tp=1 热歌榜 / tp=2 车载新歌榜
 *   封面  : huole-img.y2002.com + 同签名规则重签（防盗链 24h 时效）
 *   取链  : p 域 fd-huole-a-p 原样 musicurl（m4a，实测 ftyp、29,411,922B÷3598.785s=65.4kbps → 64k）
 *           o 域 fd-huole-a-o 去 "-{fmt}.m4a" 换 ".{fmt}" 纯格式（实测 mp3 ID3、143,953,611B÷3598.785s=320.0kbps）
 *           防盗链 sign=md5(fdKey+path+t)，t=(now+24h)/1000 小写 hex，每次实时生成
 *   诚实标注：有损档按 体积×8÷时长 反推贴最近内置档（宁低勿高）；无高品纯格式档/无源 flac 时拒而不下级
 *   歌词  : 全曲库 haslrc=0（实测 searchlrc 恒 null），无歌词接口
 *   档位归一：low/standard/64k/96k/128k→std；high/exhigh/192k/320k→pure；super/flac/lossless→lossless
 */
exports.manifest = {
  manifestVersion: 2,
  id: 'ceru.huolongdj',
  name: '火龙DJ',
  version: '1.0.0',
  description: '支持音质：64k/320k/flac',
  author: 'hebijunge',
  engines: { hostApi: '^2.0.0', logicRuntime: 'ceru-js@1' },
  modules: { logic: { entry: 'logic.main' } },
  permissions: [{ key: 'network', name: 'network.request', reason: '搜索与取链需要访问网络' }],
  contributes: {
    providers: [{
      id: "ceru.huolongdj",
      name: '火龙DJ',
      protocols: ['music.search@1', 'music.resolve@1', 'music.charts@1'],
      qualities: ['64k', '320k', 'flac'],
      connectionMode: 'none'
    }]
  }
};

